package main

import (
	"context"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"net/url"
	"strings"
	"sync"

	"github.com/segmentio/kafka-go"
)

var (
	allowedRedirectDomains = []string{"app.example.com", "dashboard.example.com"}
	oauthCallbackTemplate  *template.Template
	sessionStore           sync.Map
)

type OAuthEvent struct {
	UserID      string `json:"user_id"`
	RedirectURI string `json:"redirect_uri"`
	State       string `json:"state"`
	Code        string `json:"code"`
	ClientID    string `json:"client_id"`
}

func init() {
	oauthCallbackTemplate = template.Must(template.New("callback").Parse(`<!DOCTYPE html>
<html>
<head>
	<script src="https://cdn.example.com/oauth-sdk.js"></script>
</head>
<body>
	<script>
		window.location.href = "{{.RedirectURI}}?code={{.Code}}&state={{.State}}";
	</script>
</body>
</html>`))
}

func validateRedirectURI(redirectURI string) bool {
	parsed, err := url.Parse(redirectURI)
	if err != nil {
		return false
	}
	// Check if the host ends with an allowed domain
	for _, domain := range allowedRedirectDomains {
		if strings.HasSuffix(parsed.Host, domain) {
			return true
		}
	}
	return false
}

func processOAuthEvent(event OAuthEvent) error {
	if !validateRedirectURI(event.RedirectURI) {
		return fmt.Errorf("invalid redirect_uri: %s", event.RedirectURI)
	}
	sessionStore.Store(event.State, event)
	return nil
}

func handleOAuthCallback(w http.ResponseWriter, r *http.Request) {
	state := r.URL.Query().Get("state")
	if state == "" {
		http.Error(w, "missing state", http.StatusBadRequest)
		return
	}

	val, ok := sessionStore.Load(state)
	if !ok {
		http.Error(w, "invalid state", http.StatusBadRequest)
		return
	}

	event := val.(OAuthEvent)
	w.Header().Set("Content-Type", "text/html")
	oauthCallbackTemplate.Execute(w, event)
}

func consumeOAuthEvents(ctx context.Context) {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{"kafka:9092"},
		Topic:    "oauth-events",
		GroupID:  "oauth-processor",
		MinBytes: 10e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	for {
		select {
		case <-ctx.Done():
			return
		default:
			msg, err := reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("error reading message: %v", err)
				continue
			}

			var event OAuthEvent
			if err := json.Unmarshal(msg.Value, &event); err != nil {
				log.Printf("error unmarshaling event: %v", err)
				continue
			}

			if err := processOAuthEvent(event); err != nil {
				log.Printf("error processing event: %v", err)
			}
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go consumeOAuthEvents(ctx)

	http.HandleFunc("/oauth/callback", handleOAuthCallback)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
